function onChange(control, oldValue, newValue, isLoading) {
   alert("Deliverable Type Changed to: " + newValue);

   if (isLoading || !newValue) return;

   if (newValue == 'promo' || newValue == 'secondary_event') {
      g_form.setDisplay('end_tag_details', true);
   } else {
      g_form.setDisplay('end_tag_details', false);
   }
}
